<p class="breadcrumb"><a href="<?= e(url('/admin/clientes')) ?>">Clientes</a> / <?= e($customer['name']) ?></p><h1><?= e($customer['name']) ?></h1>
<div class="profile-grid"><section class="card"><h2>Cadastro</h2><dl class="info-list"><dt>E-mail</dt><dd><?= e($customer['email']) ?></dd><dt>Telefone</dt><dd><?= e($customer['phone'] ?: 'Não informado') ?></dd><dt>Cliente desde</dt><dd><?= e(format_date($customer['created_at'])) ?></dd><dt>Último acesso</dt><dd><?= e(format_date($customer['last_login_at'] ?? null) ?: 'Não registrado') ?></dd><dt>Total comprado</dt><dd><?= e(money($spent)) ?></dd></dl>
<?php if (isset($customer['active'])): ?><p><strong><?= (int) $customer['active'] ? 'Cliente ativo' : 'Cliente bloqueado' ?></strong></p><form method="post" action="<?= e(url('/admin/clientes/' . (int) $customer['id'] . '/situacao')) ?>" data-confirm="Alterar o acesso deste cliente à loja?"><?= csrf_field() ?><input type="hidden" name="active" value="<?= (int) $customer['active'] ? '0' : '1' ?>"><button class="btn btn-outline"><?= (int) $customer['active'] ? 'Bloquear cliente' : 'Desbloquear cliente' ?></button></form><?php endif; ?></section>
<section class="card"><h2>Endereço</h2><?php if (!$address): ?><p>Não informado.</p><?php else: ?><address class="address"><?= e($address['street']) ?>, <?= e($address['number']) ?><br><?= e($address['complement']) ?><br><?= e($address['district']) ?> · <?= e($address['city']) ?>/<?= e($address['state']) ?><br>CEP <?= e($address['cep']) ?></address><?php endif; ?></section></div>
<section class="section"><h2>Histórico de pedidos</h2><?php if (!$rows): ?><p>Nenhum pedido.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Data</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach ($rows as $order): ?><tr><td data-label="Pedido"><a href="<?= e(url('/admin/pedidos/' . (int) $order['id'])) ?>">nº <?= (int) $order['id'] ?></a></td><td data-label="Data"><?= e(format_date($order['created_at'])) ?></td><td data-label="Status"><?= e(status_label($order['status'])) ?></td><td data-label="Total"><?= e(money($order['total'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?= render_template('admin/_pagination', compact('page','pages','total') + ['path' => '/admin/clientes/' . (int) $customer['id'], 'filters' => []]) ?></section>
